1	//! The model-side runtime trait and the polling loop that drives it.
2	//!
3	//! The loop lives here — once, for every model line — so its conventions
4	//! (drain order, one metrics publish and one commit per iteration, shutdown
5	//! and fatal handling) are code, not per-crate discipline. A model line's
6	//! runtime obligation is exactly the three [`Scheduler`] methods. Anything
7	//! beyond them (e.g. LoRA control) is not the contract's business: a
8	//! scheduler that serves an extra capability captures its own channel before
9	//! spawn and drains it inside `step`.
10	
11	use super::ledger::RequestLedger;
12	use super::metrics::SchedulerMetrics;
13	use super::step::QueuedRequest;
14	use super::wiring::LiveScheduler;
15	use super::wiring::SchedulerBackend;
16	use super::wiring::scheduler_pair;
17	
18	/// One scheduler's runtime behavior. Runs on a dedicated OS thread spawned
19	/// by [`spawn_scheduler`]; `Send` suffices.
20	pub trait Scheduler: Send {
21	    /// Take ownership of one submitted request. Ownership transfer only —
22	    /// every verdict (admit/reject/retire) is written to the ledger from
23	    /// [`Self::step`], the single emission site. Nothing is lost by
24	    /// deferring: the driver commits once per iteration, so a verdict
25	    /// recorded in `step` lands in the same commit a submit-time verdict
26	    /// would have.
27	    fn submit(&mut self, request: QueuedRequest);
28	
29	    /// Advance one step: admission, GPU work, and per-request ledger writes.
30	    /// The driver loops over this without pause — an idle scheduler returns
31	    /// quickly and gets polled again, so in-flight completions from the
32	    /// scheduler's own worker threads are picked up within a step. Recoverable
33	    /// execution failures are the scheduler's to absorb (fail the touched
34	    /// requests, keep serving); `Err` means the engine is beyond use. The
35	    /// driver then writes off every open account with the error and winds
36	    /// down.
37	    fn step(&mut self, ledger: &mut RequestLedger) -> anyhow::Result<()>;
38	
39	    /// Metrics snapshot; the driver publishes it once per iteration.
40	    fn metrics(&self) -> SchedulerMetrics;
41	}
42	
43	/// Spawn one scheduler: mint the wiring, start the driver thread, return the
44	/// frontend end. `name` names the OS thread (shows in `top`/gdb).
45	pub fn spawn_scheduler<S: Scheduler + 'static>(name: &str, scheduler: S) -> LiveScheduler {
46	    let (handle, backend) = scheduler_pair();
47	    let join = std::thread::Builder::new()
48	        .name(name.to_string())
49	        .spawn(move || drive(scheduler, backend))
50	        .expect("failed to spawn scheduler thread");
51	    LiveScheduler { handle, join }
52	}
53	
54	/// The polling loop. Exits when the frontend is gone (submission channel
55	/// disconnected) and the scheduler reports itself drained, or when `step`
56	/// reports a fatal error. An idle iteration (nothing running or waiting) ends
57	/// in a [`std::hint::spin_loop`] before the next probe; busy iterations never
58	/// pause.
59	pub fn drive<S: Scheduler>(mut scheduler: S, backend: SchedulerBackend) {
60	    let SchedulerBackend {
61	        submissions,
62	        mut ledger,
63	        metrics,
64	        exit_guard: _exit_guard,
65	    } = backend;
66	    let mut submissions_open = true;
67	    loop {
68	        loop {
69	            match submissions.try_recv() {
70	                Ok(envelope) => {
71	                    let queued = ledger.register(envelope);
72	                    scheduler.submit(queued);
73	                }
74	                Err(crossbeam_channel::TryRecvError::Empty) => break,
75	                Err(crossbeam_channel::TryRecvError::Disconnected) => {
76	                    submissions_open = false;
77	                    break;
78	                }
79	            }
80	        }
81	        let step = scheduler.step(&mut ledger);
82	        let snapshot = scheduler.metrics();
83	        let metrics_changed = metrics.publish(&snapshot);
84	        ledger.commit_step(metrics_changed);
85	        if let Err(error) = step {
86	            // The ledger holds an account for every unanswered request, so
87	            // the write-off reaches them all — including any the scheduler
88	            // lost track of — with the real error attached.
89	            log::error!("scheduler fatal, engine winding down: {error:#}");
90	            ledger.fail_all(&format!("engine fatal: {error:#}"));
91	            ledger.commit_step(false);
92	            return;
93	        }
94	        if snapshot.num_running_reqs == 0 && snapshot.num_waiting_reqs == 0 {
95	            if !submissions_open {
96	                log::info!("scheduler drained after frontend shutdown, exiting");
97	                return;
98	            }
99	            // The iteration did no work; relax the core's issue slots before
100	            // probing again. Latency is untouched — busy iterations never
101	            // reach this hint.
102	            std::hint::spin_loop();
103	        }
104	    }
105	}
106	
107	#[cfg(test)]
108	mod tests {
109	    use super::super::step::Request;
110	    use super::super::step::RequestId;
111	    use super::super::step::Terminal;
112	    use super::super::stop::StopPolicy;
113	    use super::*;
114	    use crate::engine::FinishReason;
115	
116	    /// Emits one token per step per request and finishes at `max_tokens`.
117	    #[derive(Default)]
118	    struct EchoScheduler {
119	        queued: Vec<(RequestId, usize)>,
120	        running: Vec<(RequestId, usize)>,
121	        fatal_next_step: bool,
122	    }
123	
124	    impl Scheduler for EchoScheduler {
125	        fn submit(&mut self, request: QueuedRequest) {
126	            self.queued.push((request.id, request.request.max_tokens));
127	        }
128	
129	        fn step(&mut self, ledger: &mut RequestLedger) -> anyhow::Result<()> {
130	            if self.fatal_next_step && !(self.queued.is_empty() && self.running.is_empty()) {
131	                anyhow::bail!("injected fatal");
132	            }
133	            for (id, max_tokens) in self.queued.drain(..) {
134	                ledger.admit(id);
135	                self.running.push((id, max_tokens));
136	            }
137	            let mut still_running = Vec::new();
138	            for (id, max_tokens) in self.running.drain(..) {
139	                if ledger.is_aborted(id) {
140	                    ledger.retire(id);
141	                    continue;
142	                }
143	                let next = ledger.completion_tokens(id) as u32;
144	                ledger.push_tokens(id, &[next], &[]);
145	                if ledger.completion_tokens(id) >= max_tokens {
146	                    ledger.finish(id, FinishReason::Length);
147	                } else {
148	                    still_running.push((id, max_tokens));
149	                }
150	            }
151	            self.running = still_running;
152	            Ok(())
153	        }
154	
155	        fn metrics(&self) -> SchedulerMetrics {
156	            SchedulerMetrics {
157	                num_running_reqs: self.running.len() as u64,
158	                num_waiting_reqs: self.queued.len() as u64,
159	                ..SchedulerMetrics::default()
160	            }
161	        }
162	    }
163	
164	    fn request(max_tokens: usize) -> Request {
165	        Request {
166	            prompt_tokens: vec![1, 2],
167	            params: crate::sampler::SamplingParams::default(),
168	            history_tokens: None,
169	            history_marks: Vec::new(),
170	            stop_policy: StopPolicy::default(),
171	            max_tokens,
172	            lora_adapter: None,
173	            kv_transfer_params: None,
174	            logprobs: None,
175	            prompt_logprobs: None,
176	            trace_parent: None,
177	            client_label: None,
178	        }
179	    }
180	
181	    #[test]
182	    fn driven_engine_streams_and_drains_on_shutdown() {
183	        let partition = spawn_scheduler("test-echo", EchoScheduler::default());
184	        let mut handle = partition.handle;
185	        let mut steps = handle.take_steps().expect("step stream");
186	
187	        let _control = handle.submit(request(3));
188	        let mut tokens = Vec::new();
189	        let mut terminal = None;
190	        while terminal.is_none() {
191	            let step = steps.blocking_recv().expect("step message");
192	            for update in step.updates {
193	                assert!(update.scheduled.is_some() || !tokens.is_empty());
194	                tokens.extend(update.tokens);
195	                if let Some(t) = update.terminal {
196	                    terminal = Some(t);
197	                }
198	            }
199	        }
200	        assert_eq!(tokens, vec![0, 1, 2]);
201	        assert!(matches!(
202	            terminal,
203	            Some(Terminal::Finished {
204	                reason: FinishReason::Length,
205	                stop_cause: None,
206	                prompt_tokens: 2,
207	                completion_tokens: 3,
208	            })
209	        ));
210	
211	        // Dropping the handle disconnects the submission channel; a drained
212	        // scheduler exits.
213	        drop(handle);
214	        partition.join.join().expect("driver thread exits cleanly");
215	    }
216	
217	    #[test]
218	    fn cancellation_notifies_metrics_once_without_request_output() {
219	        struct PausedScheduler {
220	            queued: Vec<RequestId>,
221	            running: Vec<RequestId>,
222	            entered: std::sync::mpsc::Sender<()>,
223	            resume: std::sync::mpsc::Receiver<()>,
224	        }
225	
226	        impl Scheduler for PausedScheduler {
227	            fn submit(&mut self, request: QueuedRequest) {
228	                self.queued.push(request.id);
229	            }
230	
231	            fn step(&mut self, ledger: &mut RequestLedger) -> anyhow::Result<()> {
232	                let _ = self.entered.send(());
233	                let _ = self.resume.recv();
234	                for id in self.queued.drain(..) {
235	                    ledger.admit(id);
236	                    self.running.push(id);
237	                }
238	                self.running.retain(|&id| {
239	                    if ledger.is_aborted(id) {
240	                        ledger.retire(id);
241	                        false
242	                    } else {
243	                        true
244	                    }
245	                });
246	                Ok(())
247	            }
248	
249	            fn metrics(&self) -> SchedulerMetrics {
250	                SchedulerMetrics {
251	                    num_running_reqs: self.running.len() as u64,
252	                    ..SchedulerMetrics::default()
253	                }
254	            }
255	        }
256	
257	        let (mut handle, backend) = scheduler_pair();
258	        let mut steps = handle.take_steps().unwrap();
259	        let control = handle.submit(request(8));
260	        let (entered_tx, entered_rx) = std::sync::mpsc::channel();
261	        let (resume_tx, resume_rx) = std::sync::mpsc::channel();
262	        let join = std::thread::spawn(move || {
263	            drive(
264	                PausedScheduler {
265	                    queued: Vec::new(),
266	                    running: Vec::new(),
267	                    entered: entered_tx,
268	                    resume: resume_rx,
269	                },
270	                backend,
271	            );
272	        });
273	        let next_step = || {
274	            entered_rx
275	                .recv_timeout(std::time::Duration::from_secs(5))
276	                .expect("driver advanced to its next step");
277	        };
278	
279	        next_step();
280	        resume_tx.send(()).unwrap();
281	        next_step();
282	        steps.try_recv().expect("admission step");
283	
284	        control.abort();
285	        resume_tx.send(()).unwrap();
286	        next_step();
287	        assert!(
288	            steps
289	                .try_recv()
290	                .expect("cancellation load change")
291	                .updates
292	                .is_empty()
293	        );
294	        assert_eq!(handle.metrics().num_running_reqs, 0);
295	
296	        resume_tx.send(()).unwrap();
297	        next_step();
298	        assert!(matches!(
299	            steps.try_recv(),
300	            Err(tokio::sync::mpsc::error::TryRecvError::Empty)
301	        ));
302	        drop(handle);
303	        drop(resume_tx);
304	        join.join().expect("driver drains after cancellation");
305	    }
306	
307	    #[test]
308	    fn fatal_step_fails_in_flight_requests_with_the_error() {
309	        let partition = spawn_scheduler(
310	            "test-fatal",
311	            EchoScheduler {
312	                fatal_next_step: true,
313	                ..EchoScheduler::default()
314	            },
315	        );
316	        let mut handle = partition.handle;
317	        let mut steps = handle.take_steps().expect("step stream");
318	
319	        let _control = handle.submit(request(100));
320	        let mut failure_message = None;
321	        while let Some(step) = steps.blocking_recv() {
322	            for update in step.updates {
323	                if let Some(Terminal::Failed { message, .. }) = update.terminal {
324	                    failure_message = Some(message);
325	                }
326	            }
327	            if failure_message.is_some() {
328	                break;
329	            }
330	        }
331	        let message = failure_message.expect("in-flight request must be answered on fatal");
332	        assert!(
333	            message.contains("injected fatal"),
334	            "the write-off must carry the real error: {message}"
335	        );
336	        partition
337	            .join
338	            .join()
339	            .expect("driver thread exits after fatal");
340	    }
341	}
